/* @lc app=leetcode id=2685 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun countCompleteComponents(n: Int, edges: Array<IntArray>): Int = IntArray(n) { it }.let { p -> edges.forEach { (a, b) -> p[find(p, a)] = find(p, b) }.let { (0 until n).groupBy { find(p, it) }.values.count { c -> edges.count { find(p, it[0]) == find(p, c[0]) } == c.size * (c.size - 1) / 2 } } } }